def convert_li(self, el, text, convert_as_inline):
    if convert_as_inline:
        return text

    parent = el.parent
    if not parent:
        return text

    # Calculate the depth of nesting
    depth = 0
    parent_list = el.parent
    while parent_list and parent_list.name in ['ul', 'ol']:
        depth += 1
        parent_list = parent_list.parent

    # Process text for multi-line content
    text = text.rstrip()
    if '\n' in text:
        lines = text.split('\n')
        # Apply indentation to all lines after the first one
        text = lines[0]
        for line in lines[1:]:
            if parent.name == 'ol':
                # For ordered lists, indent based on the number width
                indent_size = 6  # Default for numbers < 10
                if len(str(len(parent.find_all('li')))) > 1:
                    indent_size += len(str(len(parent.find_all('li')))) - 1
                text += '\n' + ' ' * indent_size + line
            else:
                # For unordered lists, indent 2 spaces
                text += '\n' + '  ' + line

    if parent.name == 'ol':
        # Get the start number for ordered lists
        start = 1
        if parent.get('start'):
            try:
                start = int(parent['start'])
                # Handle negative or non-integer start values
                if start < 1:
                    start = 1
            except (ValueError, TypeError):
                start = 1

        # Count only direct li children
        index = 0
        for sibling in el.previous_siblings:
            if sibling.name == 'li':
                index += 1

        bullet = '%d.' % (start + index)

        # For nested ordered lists
        if depth > 1:
            indent = ' ' * 3 * (depth - 1)
            return indent + bullet + ' ' + text.strip() + '\n'
        else:
            return bullet + ' ' + text.strip() + '\n'
    else:
        # Unordered list
        bullets = self.options['bullets']
        bullet_index = (depth - 1) % len(bullets)
        bullet = bullets[bullet_index]

        # For nested unordered lists
        if depth > 1:
            if depth == 2:
                indent = '  '  # 2 spaces for first level nesting
            else:
                indent = '  ' + ' ' * 2 * (depth - 2)  # 2 spaces for each additional level
            return indent + bullet + ' ' + text.strip() + '\n'
        else:
            return bullet + ' ' + text.strip() + '\n'

